waves.point_eqs_eel:
//init
zs = if(below(zs,100),100,zs);
zs = if(above(zs, 10100),100, zs);

zs = if(above(zs, 1100),1, zs);

//sum
zs = 1*sample*0.1;

//draw
//ring
ring1x  = 0.1*cos(q1*zs*1);
ring1y =  0.1*sin(q1*zs*1);

ring2x  = 0.1*cos(q1*zs*1.1);
ring2y =  0.1*sin(q1*zs*1.1);

ring3x  = 0.1*cos(q1*zs*1.2);
ring3y =  0.1*sin(q1*zs*1.2);

ring4x  = 0.1*cos(q1*zs*1.3);
ring4y =  0.1*sin(q1*zs*1.3);

ring5x  = 0.1*cos(q1*zs*1.4);
ring5y =  0.1*sin(q1*zs*1.4);

//rotate
ring1x = ring1x*cos(q1*0.1) - ring1y*sin(q1*0.1);
ring1y = ring1x*sin(q1*0.1) + ring1y*cos(q1*0.1);

ring2x = ring2x*cos(q1*0.2) - ring2y*sin(q1*0.2);
ring2y = ring2x*sin(q1*0.2) + ring2y*cos(q1*0.2);

ring3x = ring3x*cos(q1*0.3) - ring3y*sin(q1*0.3);
ring3y = ring3x*sin(q1*0.3) + ring3y*cos(q1*0.3);

ring4x = ring4x*cos(q1*0.4) - ring4y*sin(q1*0.4);
ring4y = ring4x*sin(q1*0.4) + ring4y*cos(q1*0.4);

ring5x = ring5x*cos(q1*0.5) - ring5y*sin(q1*0.5);
ring5y = ring5x*sin(q1*0.5) + ring5y*cos(q1*0.5);

//rotate
//x = x*cos(q1*0.6) - y*sin(q1*0.6);
//y = x*sin(q1*0.6) + y*cos(q1*0.6);

//place
x = ring1x  + ring2x + ring3x + ring4x + ring5x + 0.5;
y = ring1y  + ring2y + ring3y + ring4y + ring5y + 0.5;

r =1;
g =1;
b =1;

//init
zs = if(below(zs,100),100,zs);
zs = if(above(zs, 10100),100, zs);

zs = if(above(zs, 1100),1, zs);

zs = 1*sample*0.1;

//draw
//ring
ring1x  = 0.1*cos(q1*zs*1);
ring1y =  0.1*sin(q1*zs*1);

ring2x  = 0.1*cos(q1*zs*1.1);
ring2y =  0.1*sin(q1*zs*1.1);

ring3x  = 0.1*cos(q1*zs*1.2);
ring3y =  0.1*sin(q1*zs*1.2);

ring4x  = 0.1*cos(q1*zs*1.3);
ring4y =  0.1*sin(q1*zs*1.3);

ring5x  = 0.1*cos(q1*zs*1.4);
ring5y =  0.1*sin(q1*zs*1.4);

//rotate
ring1x = ring1x*cos(q1*0.1) - ring1y*sin(q1*0.1);
ring1y = ring1x*sin(q1*0.1) + ring1y*cos(q1*0.1);

ring2x = ring2x*cos(q1*0.2) - ring2y*sin(q1*0.2);
ring2y = ring2x*sin(q1*0.2) + ring2y*cos(q1*0.2);

ring3x = ring3x*cos(q1*0.3) - ring3y*sin(q1*0.3);
ring3y = ring3x*sin(q1*0.3) + ring3y*cos(q1*0.3);

ring4x = ring4x*cos(q1*0.4) - ring4y*sin(q1*0.4);
ring4y = ring4x*sin(q1*0.4) + ring4y*cos(q1*0.4);

ring5x = ring5x*cos(q1*0.5) - ring5y*sin(q1*0.5);
ring5y = ring5x*sin(q1*0.5) + ring5y*cos(q1*0.5);

//place
x = ring1x  + ring2x + ring3x + ring4x + ring5x + 0.5;
y = ring1y  + ring2y + ring3y + ring4y + ring5y + 0.5;

r = 0.5 + 0.5*sin(q1*1.2 + x + x);
g = 0.5 + 0.5*sin(q1*1.5 + x + y);
b = 0.5 + 0.5*sin(q1*1.36 + y + y);

preset.frame_eqs_eel:
basstime = basstime + bass*0.03;
basstime2 = basstime + bass*0.03;
q1 = basstime2;

//start in most active range
basstime = if(below(basstime,1000),1000,basstime);
//basstime = if(above(basstime,495),450,basstime);

basstime = basstime + bass_att*0.03;
vol = pow(bass+mid+treb,2);
basssum = vol;

stickybit = time%2;

//avg vol
//buffer 1
volAvg = volAvg + vol*equal(stickybit,1);
//number of samples 1 or framerate
sample1 = sample1 + equal(stickybit,1);
//buffer 2
volAvg2 = volAvg2 + vol*equal(stickybit,0);
//number of samples 2
sample2 = sample2 + equal(stickybit,0);

//transision
edge = bnot(equal(bit2,stickybit));

volAvg = volAvg - volAvg*edge*stickybit;
volAvg2 = volAvg2 - volAvg2*edge*equal(stickybit,0);

sample1 = sample1  - sample1*edge*stickybit;
sample2 = sample2  - sample2*edge*equal(stickybit,0);

//test vol against avg buffer lvl
diff = if(equal(stickybit,1), (basssum/(volAvg2/sample2)) , 0);
diff = if(equal(stickybit,0), (basssum/(volAvg/sample1)), diff);

q3 = diff;

bit2 = time%2;

difftime = difftime + diff*0.03;
q2 = difftime;

//fix a strange error
difftime = if(above(difftime,2000),0, difftime);

monitor = q1;

rarr = rand(100)*0.01;

decay = 0.7 + 0.2*(abs(cos(difftime*1.56+rarr)));

//shape fill
q8 = (diff+1)*0.0001;
